  /* ── ABOUT (homepage) ────────────────────────────── */
  'about.eyebrow':  { pt: 'Sobre',  en: 'About Us',  fr: 'À propos' },
  'about.title':    { pt: 'Veio ao sítio certo. Profissionalismo, Confiança e Excelência', en: 'You\'ve come to the right place. Professionalism, Trust and Excellence', fr: 'Vous êtes au bon endroit. Professionnalisme, Confiance et Excellence' },
  'about.p1':       { pt: 'A Pharus AI Agency é especializada na criação de soluções de Inteligência Artificial que transformam a forma como as empresas operam, comunicam e crescem.', en: 'Pharus AI Agency specialises in creating Artificial Intelligence solutions that transform the way companies operate, communicate and grow.', fr: 'Pharus AI Agency est spécialisée dans la création de solutions d\'Intelligence Artificielle qui transforment la façon dont les entreprises opèrent, communiquent et se développent.' },
  'about.p2':       { pt: 'Aliamos experiência em tecnologia, negócios e automação para desenvolver <strong>agentes de IA, assistentes inteligentes, sistemas de geração de conteúdos, automações de processos</strong> e soluções personalizadas capazes de aumentar a produtividade e reduzir custos operacionais.', en: 'We combine expertise in technology, business and automation to develop <strong>AI agents, intelligent assistants, content generation systems, process automations</strong> and personalised solutions capable of increasing productivity and reducing operational costs.', fr: 'Nous combinons une expertise en technologie, en gestion et en automatisation pour développer des <strong>agents IA, des assistants intelligents, des systèmes de génération de contenu, des automatisations de processus</strong> et des solutions personnalisées capables d\'augmenter la productivité et de réduire les coûts opérationnels.' },
  'about.p3':       { pt: 'Trabalhamos com empresas de diferentes setores, ajudando-as a identificar oportunidades de otimização e a implementar soluções inovadoras com impacto real nos resultados. Cada projeto é concebido de forma estratégica, garantindo uma integração eficiente com os processos existentes e uma rápida geração de valor.', en: 'We work with companies from different sectors, helping them identify optimisation opportunities and implement innovative solutions with a real impact on results. Each project is designed strategically, ensuring efficient integration with existing processes and rapid value generation.', fr: 'Nous travaillons avec des entreprises de différents secteurs, en les aidant à identifier des opportunités d\'optimisation et à mettre en œuvre des solutions innovantes ayant un impact réel sur les résultats. Chaque projet est conçu de manière stratégique, garantissant une intégration efficace avec les processus existants et une génération rapide de valeur.' },
  'about.p4':       { pt: 'O nosso compromisso centra-se na excelência, inovação e confiança. Criamos soluções de Inteligência Artificial seguras, escaláveis e orientadas para resultados, permitindo que as organizações se concentrem no que realmente importa: crescer, inovar e liderar o seu mercado.', en: 'Our commitment centres on excellence, innovation and trust. We create safe, scalable and results-oriented Artificial Intelligence solutions, enabling organisations to focus on what truly matters: growing, innovating and leading their market.', fr: 'Notre engagement est axé sur l\'excellence, l\'innovation et la confiance. Nous créons des solutions d\'Intelligence Artificielle sûres, évolutives et orientées résultats, permettant aux organisations de se concentrer sur ce qui compte vraiment : croître, innover et diriger leur marché.' },
  'about.f1':       { pt: 'Atendimento personalizado em Português, Inglês e Francês', en: 'Personalised service in Portuguese, English and French', fr: 'Service personnalisé en portugais, anglais et français' },
  'about.f2':       { pt: 'Da ideia à execução. IA com acompanhamento especializado.', en: 'From idea to execution. AI with expert guidance.', fr: 'De l\'idée à l\'exécution. IA avec accompagnement expert.' },
  'about.f3':       { pt: 'Trabalhamos lado a lado consigo para identificar oportunidades, implementar soluções inteligentes e maximizar resultados.', en: 'We work side by side with you to identify opportunities, implement intelligent solutions and maximise results.', fr: 'Nous travaillons côte à côte avec vous pour identifier les opportunités, mettre en œuvre des solutions intelligentes et maximiser les résultats.' },
