  'areas.intro':    { pt: 'Ajudamos empresas a tirar partido da Inteligência Artificial através de:<br><br>• Agentes de IA e Assistentes Virtuais<br>• Automação de Processos Empresariais<br>• Chatbots Inteligentes<br>• IA para Marketing e Vendas<br>• Geração Automática de Conteúdos<br>• Análise de Dados e Business Intelligence<br>• Integração de Sistemas e APIs<br>• Formação e Consultoria em IA<br>• Desenvolvimento de Soluções Personalizadas<br>• Transformação Digital e Inovação Empresarial', en: 'We help companies harness Artificial Intelligence through:<br><br>• AI Agents and Virtual Assistants<br>• Business Process Automation<br>• Intelligent Chatbots<br>• AI for Marketing and Sales<br>• Automatic Content Generation<br>• Data Analytics and Business Intelligence<br>• Systems and API Integration<br>• AI Training and Consulting<br>• Custom Solution Development<br>• Digital Transformation and Business Innovation', fr: 'Nous aidons les entreprises à tirer parti de l\'Intelligence Artificielle grâce à :<br><br>• Agents IA et Assistants Virtuels<br>• Automatisation des Processus Métier<br>• Chatbots Intelligents<br>• IA pour le Marketing et les Ventes<br>• Génération Automatique de Contenus<br>• Analyse de Données et Business Intelligence<br>• Intégration de Systèmes et d\'APIs<br>• Formation et Conseil en IA<br>• Développement de Solutions Personnalisées<br>• Transformation Numérique et Innovation' },
  'area.imob.title': { pt: 'Agentes de Inteligência Artificial', en: 'Artificial Intelligence Agents', fr: 'Agents d\'Intelligence Artificielle' },
  'area.imob.desc':  { pt: 'Desenvolvimento de agentes autónomos capazes de executar tarefas, interagir com clientes, apoiar equipas e automatizar processos empresariais com elevada eficiência.', en: 'Development of autonomous agents capable of executing tasks, interacting with clients, supporting teams and automating business processes with high efficiency.', fr: 'Développement d\'agents autonomes capables d\'exécuter des tâches, d\'interagir avec les clients, d\'accompagner les équipes et d\'automatiser les processus d\'entreprise avec une haute efficacité.' },
  'area.soc.title':  { pt: 'Automação de Processos', en: 'Process Automation', fr: 'Automatisation des processus' },
  'area.soc.desc':   { pt: 'Identificação, otimização e automatização de tarefas repetitivas através de Inteligência Artificial e integração de sistemas, reduzindo custos operacionais e aumentando a produtividade.', en: 'Identification, optimisation and automation of repetitive tasks through Artificial Intelligence and systems integration, reducing operational costs and increasing productivity.', fr: 'Identification, optimisation et automatisation des tâches répétitives grâce à l\'Intelligence Artificielle et à l\'intégration de systèmes, réduisant les coûts opérationnels et augmentant la productivité.' },
  'area.mig.title':  { pt: 'Assistentes Virtuais e Chatbots', en: 'Virtual Assistants & Chatbots', fr: 'Assistants virtuels et chatbots' },
  'area.mig.desc':   { pt: 'Criação de assistentes inteligentes para websites, atendimento ao cliente, suporte técnico e equipas internas, disponíveis 24 horas por dia.', en: 'Creation of intelligent assistants for websites, customer service, technical support and internal teams, available 24 hours a day.', fr: 'Création d\'assistants intelligents pour les sites web, le service client, le support technique et les équipes internes, disponibles 24 heures sur 24.' },
  'area.nac.title':  { pt: 'Estratégia e Consultoria em IA', en: 'AI Strategy & Consulting', fr: 'Stratégie et conseil en IA' },
  'area.nac.desc':   { pt: 'Definição de estratégias de adoção de Inteligência Artificial alinhadas com os objetivos do negócio. Avaliação de oportunidades, desenho de soluções e acompanhamento da implementação.', en: 'Defining Artificial Intelligence adoption strategies aligned with business objectives. Opportunity assessment, solution design and implementation support.', fr: 'Définition de stratégies d\'adoption de l\'Intelligence Artificielle alignées sur les objectifs de l\'entreprise. Évaluation des opportunités, conception de solutions et accompagnement à la mise en œuvre.' },

  /* ── WHY SECTION ─────────────────────────────────── */
  'why.eyebrow':    { pt: 'Porque Nos Escolher',   en: 'Why Choose Us',          fr: 'Pourquoi nous choisir' },
  'why.title':      { pt: 'Porque Escolher a Pharus AI Agency?', en: 'Why Choose Pharus AI Agency?', fr: 'Pourquoi choisir Pharus AI Agency ?' },
  'why.c1.title':   { pt: 'Experiência e Conhecimento Especializado', en: 'Experience & Specialist Knowledge', fr: 'Expérience et expertise spécialisée' },
  'why.c1.desc':    { pt: 'Combinamos experiência empresarial, tecnológica e estratégica para desenvolver soluções de Inteligência Artificial que geram resultados concretos. Aplicamos as melhores práticas do mercado e as tecnologias mais avançadas para responder aos desafios específicos de cada organização.', en: 'We combine business, technological and strategic expertise to develop AI solutions that generate concrete results. We apply best market practices and the most advanced technologies to address each organisation\'s specific challenges.', fr: 'Nous combinons une expertise en affaires, technologique et stratégique pour développer des solutions IA qui génèrent des résultats concrets. Nous appliquons les meilleures pratiques du marché et les technologies les plus avancées pour répondre aux défis spécifiques de chaque organisation.' },
  'why.c2.title':   { pt: 'Soluções Personalizadas', en: 'Tailored Solutions', fr: 'Solutions personnalisées' },
  'why.c2.desc':    { pt: 'Cada empresa tem objetivos, processos e desafios próprios. Desenvolvemos soluções de IA adaptadas à realidade de cada cliente, garantindo uma implementação alinhada com as necessidades do negócio e um retorno mensurável do investimento.', en: 'Every company has its own objectives, processes and challenges. We develop AI solutions adapted to each client\'s reality, ensuring implementation aligned with business needs and a measurable return on investment.', fr: 'Chaque entreprise a ses propres objectifs, processus et défis. Nous développons des solutions IA adaptées à la réalité de chaque client, garantissant une mise en œuvre alignée sur les besoins de l\'entreprise et un retour sur investissement mesurable.' },
  'why.c3.title':   { pt: 'Acompanhamento Próximo', en: 'Close Support', fr: 'Accompagnement étroit' },
  'why.c3.desc':    { pt: 'Acompanhamos cada projeto desde a análise inicial até à implementação e evolução contínua das soluções. Trabalhamos em estreita colaboração com os nossos clientes para assegurar uma adoção eficaz e uma geração de valor sustentada.', en: 'We accompany each project from initial analysis through to implementation and continuous evolution of solutions. We work in close collaboration with our clients to ensure effective adoption and sustained value generation.', fr: 'Nous accompagnons chaque projet depuis l\'analyse initiale jusqu\'à la mise en œuvre et l\'évolution continue des solutions. Nous travaillons en étroite collaboration avec nos clients pour assurer une adoption efficace et une génération de valeur durable.' },
