  'sobre.p1': { pt: 'A Pharus AI Agency ajuda empresas a transformar o potencial da Inteligência Artificial em resultados concretos.', en: 'Pharus AI Agency helps companies transform the potential of Artificial Intelligence into concrete results.', fr: 'Pharus AI Agency aide les entreprises à transformer le potentiel de l\'Intelligence Artificielle en résultats concrets.' },
  'sobre.p2': { pt: 'Especializamo-nos na conceção e implementação de agentes inteligentes, automações empresariais, assistentes virtuais, dashboards, aplicações e soluções digitais que simplificam operações e aumentam a eficiência organizacional.', en: 'We specialise in the design and implementation of intelligent agents, business automations, virtual assistants, dashboards, applications and digital solutions that simplify operations and increase organisational efficiency.', fr: 'Nous sommes spécialisés dans la conception et la mise en œuvre d\'agents intelligents, d\'automatisations d\'entreprise, d\'assistants virtuels, de tableaux de bord, d\'applications et de solutions numériques qui simplifient les opérations et augmentent l\'efficacité organisationnelle.' },
  'sobre.p3': { pt: 'Combinamos experiência em engenharia, sistemas de informação, gestão empresarial e inovação tecnológica para desenvolver soluções que respondem aos desafios reais das organizações.', en: 'We combine expertise in engineering, information systems, business management and technological innovation to develop solutions that address the real challenges of organisations.', fr: 'Nous combinons une expertise en ingénierie, systèmes d\'information, gestion d\'entreprise et innovation technologique pour développer des solutions qui répondent aux défis réels des organisations.' },
  'sobre.p4': { pt: 'Cada projeto é construído sobre três pilares fundamentais: estratégia, tecnologia e resultados. O objetivo consiste em criar soluções escaláveis, seguras e capazes de gerar valor sustentável a longo prazo.', en: 'Each project is built on three fundamental pillars: strategy, technology and results. The aim is to create scalable, secure solutions capable of generating sustainable long-term value.', fr: 'Chaque projet est construit sur trois piliers fondamentaux : stratégie, technologie et résultats. L\'objectif consiste à créer des solutions évolutives, sécurisées et capables de générer une valeur durable à long terme.' },
  'sobre.p5': { pt: 'Prestamos apoio a clientes nacionais e internacionais em Português, Inglês e Francês, assegurando uma colaboração eficaz em ambientes empresariais multiculturais.', en: 'We support national and international clients in Portuguese, English and French, ensuring effective collaboration in multicultural business environments.', fr: 'Nous accompagnons des clients nationaux et internationaux en portugais, anglais et français, assurant une collaboration efficace dans des environnements d\'entreprise multiculturels.' },
  'sobre.values.eyebrow': { pt: 'Os Nossos Valores', en: 'Our Values',    fr: 'Nos valeurs' },
  'sobre.values.title':   { pt: 'O que nos define',  en: 'What defines us', fr: 'Ce qui nous définit' },
  'sobre.v1.title': { pt: 'Integridade',  en: 'Integrity',    fr: 'Intégrité' },
  'sobre.v1.desc':  { pt: 'Atuamos sempre com honestidade e transparência, colocando os interesses do cliente em primeiro lugar e garantindo uma relação de total confiança.', en: 'We always act with honesty and transparency, putting the client\'s interests first and ensuring a relationship of complete trust.', fr: 'Nous agissons toujours avec honnêteté et transparence, plaçant les intérêts du client en premier et garantissant une relation de totale confiance.' },
  'sobre.v2.title': { pt: 'Excelência',   en: 'Excellence',   fr: 'Excellence' },
  'sobre.v2.desc':  { pt: 'Assumimos um compromisso permanente com a inovação, a qualidade e a melhoria contínua, integrando os avanços mais recentes em Inteligência Artificial para garantir soluções modernas, eficazes e preparadas para o futuro.', en: 'We make a permanent commitment to innovation, quality and continuous improvement, integrating the latest advances in Artificial Intelligence to ensure modern, effective and future-ready solutions.', fr: 'Nous prenons un engagement permanent envers l\'innovation, la qualité et l\'amélioration continue, en intégrant les dernières avancées en Intelligence Artificielle pour garantir des solutions modernes, efficaces et prêtes pour l\'avenir.' },
  'sobre.v3.title': { pt: 'Proximidade',  en: 'Proximity',    fr: 'Proximité' },
  'sobre.v3.desc':  { pt: 'Cada cliente recebe atenção individualizada. Acompanhamos cada processo de perto, mantendo o cliente informado em cada etapa.', en: 'Each client receives individual attention. We monitor every case closely, keeping the client informed at every step.', fr: 'Chaque client reçoit une attention individualisée. Nous suivons chaque dossier de près, tenant le client informé à chaque étape.' },
  'sobre.cta.title': { pt: 'Precisa de apoio jurídico especializado?', en: 'Do you need specialist legal support?', fr: 'Avez-vous besoin d\'un soutien juridique spécialisé ?' },
  'sobre.cta.desc':  { pt: 'A nossa equipa está disponível para o ajudar. Contacte-nos e agende a sua consulta.', en: 'Our team is available to help you. Contact us and book your consultation.', fr: 'Notre équipe est disponible pour vous aider. Contactez-nous et réservez votre consultation.' },

  /* ── ÁREAS PAGE ──────────────────────────────────── */
  'areas.page.eyebrow': { pt: 'Especialidades', en: 'Specialities', fr: 'Spécialités' },
  'areas.page.title':   { pt: 'Áreas de Atuação',  en: 'Practice Areas', fr: 'Domaines d\'activité' },
  'areas.page.intro':   { pt: 'Desenvolvemos soluções de Inteligência Artificial, automação e inovação digital para empresas que procuram crescer, otimizar processos e aumentar a sua competitividade.', en: 'We develop Artificial Intelligence, automation and digital innovation solutions for companies seeking to grow, optimise processes and increase their competitiveness.', fr: 'Nous développons des solutions d\'Intelligence Artificielle, d\'automatisation et d\'innovation numérique pour les entreprises souhaitant croître, optimiser leurs processus et accroître leur compétitivité.' },
  'areas.page.cta.title': { pt: 'Cada empresa tem oportunidades únicas para aplicar Inteligência Artificial.', en: 'Every company has unique opportunities to apply Artificial Intelligence.', fr: 'Chaque entreprise a des opportunités uniques pour appliquer l\'Intelligence Artificielle.' },
  'areas.page.cta.desc':  { pt: 'Agende uma reunião com a Pharus AI Agency e descubra onde a automação, os agentes inteligentes e as soluções de IA podem gerar mais valor para o seu negócio.', en: 'Schedule a meeting with Pharus AI Agency and discover where automation, intelligent agents and AI solutions can generate the most value for your business.', fr: 'Planifiez une réunion avec Pharus AI Agency et découvrez où l\'automatisation, les agents intelligents et les solutions IA peuvent générer le plus de valeur pour votre entreprise.' },

