  'art.intro':      { pt: 'Partilhamos conhecimento jurídico atualizado para ajudar os nossos clientes a navegar pelo sistema legal português.', en: 'We share up-to-date legal knowledge to help our clients navigate the Portuguese legal system.', fr: 'Nous partageons des connaissances juridiques actualisées pour aider nos clients à naviguer dans le système juridique portugais.' },
  'art.cta.title':  { pt: 'Tem questões jurídicas específicas?', en: 'Do you have specific legal questions?', fr: 'Avez-vous des questions juridiques spécifiques ?' },
  'art.cta.desc':   { pt: 'Não encontrou o que procurava? Contacte-nos directamente e a nossa equipa terá todo o gosto em esclarecer as suas dúvidas.', en: 'Didn\'t find what you were looking for? Contact us directly and our team will be happy to answer your questions.', fr: 'Vous n\'avez pas trouvé ce que vous cherchiez ? Contactez-nous directement et notre équipe se fera un plaisir de répondre à vos questions.' },
