  /* ── SOBRE BIO EXPAND ────────────────────────────── */
  'sobre.bio1': { pt: 'Sou Engenheiro de Sistemas e Computadores pelo Instituto Superior Técnico. Possuo formação avançada em gestão, energia, inovação tecnológica e Inteligência Artificial. Ao longo da minha carreira, lidero projetos empresariais em diferentes setores, sempre com um foco claro na criação de valor através da tecnologia.', en: 'I am a Computer and Systems Engineer from Instituto Superior Técnico. I have advanced training in management, energy, technological innovation and Artificial Intelligence. Throughout my career, I have led business projects across different sectors, always with a clear focus on creating value through technology.', fr: 'Je suis Ingénieur en Systèmes Informatiques de l\'Instituto Superior Técnico. Je possède une formation avancée en gestion, énergie, innovation technologique et Intelligence Artificielle. Tout au long de ma carrière, j\'ai dirigé des projets d\'entreprise dans différents secteurs, toujours avec un objectif clair de création de valeur par la technologie.' },
  'sobre.bio2': { pt: 'Hoje dedico-me a ajudar empresas a aproveitar o potencial da Inteligência Artificial para automatizar processos, aumentar a eficiência operacional e acelerar o crescimento.', en: 'Today I dedicate myself to helping companies harness the potential of Artificial Intelligence to automate processes, increase operational efficiency and accelerate growth.', fr: 'Aujourd\'hui, je me consacre à aider les entreprises à exploiter le potentiel de l\'Intelligence Artificielle pour automatiser les processus, augmenter l\'efficacité opérationnelle et accélérer la croissance.' },
  'sobre.bio3': { pt: 'Acredito que a tecnologia só faz sentido quando resolve problemas reais. Por isso, cada solução que desenvolvo parte de uma compreensão profunda do negócio, dos seus desafios e dos seus objetivos.', en: 'I believe technology only makes sense when it solves real problems. That is why every solution I develop starts from a deep understanding of the business, its challenges and its objectives.', fr: 'Je crois que la technologie n\'a de sens que lorsqu\'elle résout de vrais problèmes. C\'est pourquoi chaque solution que je développe part d\'une compréhension approfondie de l\'entreprise, de ses défis et de ses objectifs.' },
  'sobre.bio4': { pt: 'Através da Pharus AI Agency, combino experiência empresarial, conhecimento tecnológico e visão estratégica para criar soluções de IA que transformam organizações e geram resultados mensuráveis.', en: 'Through Pharus AI Agency, I combine business experience, technological knowledge and strategic vision to create AI solutions that transform organisations and generate measurable results.', fr: 'À travers Pharus AI Agency, je combine expérience professionnelle, savoir-faire technologique et vision stratégique pour créer des solutions IA qui transforment les organisations et génèrent des résultats mesurables.' },
  'sobre.bio5': { pt: 'O compromisso mantém-se inalterado: entregar inovação com propósito, tecnologia com impacto e soluções que ajudam os clientes a alcançar os seus objetivos com maior rapidez, eficiência e confiança.', en: 'The commitment remains unchanged: to deliver innovation with purpose, technology with impact and solutions that help clients achieve their goals with greater speed, efficiency and confidence.', fr: 'L\'engagement reste inchangé : livrer de l\'innovation avec un objectif, de la technologie avec un impact et des solutions qui aident les clients à atteindre leurs objectifs avec plus de rapidité, d\'efficacité et de confiance.' },
  'sobre.exp':       { pt: '+25 anos de experiência', en: '+25 years of experience', fr: '+25 ans d\'expérience' },
  'sobre.saberMais': { pt: 'Saber mais...', en: 'Find out more...', fr: 'En savoir plus...' },
  'sobre.saberMenos': { pt: 'Saber menos...', en: 'Show less...', fr: 'Réduire...' },

