  'area.imob.li1': { pt: 'Diagnóstico de oportunidades de implementação de IA ética', en: 'Ethical AI implementation opportunity assessment', fr: 'Diagnostic d\'opportunités de mise en œuvre de l\'IA éthique' },
  'area.imob.li2': { pt: 'Planeamento de arquitetura de copilotos e agentes de IA', en: 'Copilot and AI agent architecture planning', fr: 'Planification de l\'architecture de copilotos et d\'agents IA' },
  'area.imob.li3': { pt: 'Formação de equipas para utilização eficaz da Inteligência Artificial', en: 'Team training for effective use of Artificial Intelligence', fr: 'Formation des équipes à l\'utilisation efficace de l\'Intelligence Artificielle' },
  'area.imob.li4': { pt: 'Desenvolvimento de dashboards, aplicações e websites', en: 'Development of dashboards, applications and websites', fr: 'Développement de tableaux de bord, d\'applications et de sites web' },
  'area.soc.li1':    { pt: 'Comportamentos pré-programados (ex: responder clientes, recolher dados, enviar relatórios)', en: 'Pre-programmed behaviours (e.g.: responding to clients, collecting data, sending reports)', fr: 'Comportements préprogrammés (ex : répondre aux clients, collecter des données, envoyer des rapports)' },
  'area.soc.li2':    { pt: 'Workflows inteligentes, reativos e proactivos com tomada de decisão baseada em regras ou IA (ex., agente que monitora e responde clientes automaticamente)', en: 'Intelligent, reactive and proactive workflows with rule-based or AI decision-making (e.g., agent that monitors and responds to clients automatically)', fr: 'Workflows intelligents, réactifs et proactifs avec prise de décision basée sur des règles ou l\'IA (ex., agent qui surveille et répond aux clients automatiquement)' },
