  /* ── ÁREAS PAGE — CAROUSEL SLIDES (EN/FR) ─────────── */
  'carousel.ia-particulares-empresas.h3': { en: 'Artificial Intelligence for Individuals and Businesses', fr: 'Intelligence Artificielle pour Particuliers et Entreprises' },
  'carousel.ia-particulares-empresas.p':  { en: 'We develop AI solutions tailored to each client\'s needs.', fr: 'Nous développons des solutions IA adaptées aux besoins de chaque client.' },
  'carousel.ia-particulares-empresas.ul': {
    en: '<li class="area-list-subhead">Ready to create your next project?</li><li>Do you want to develop your visual identity, Brand Book and integrate it by creating a website, app, dashboard or AI agent consistent with your brand?</li><li>Do you want to learn to build professional digital solutions using the most advanced tools on the market?</li><li>Schedule a strategic meeting with Pharus AI and discover how to turn an idea into a real product, with professional mentoring of excellence.</li><li class="area-list-subhead">Strategic Consulting</li><li>We help define the best technological strategy for each situation.</li><li class="area-list-subhead">Complete Journey</li><li>From the company\'s Visual Identity, Brand Book, to Design, to the creation of a website, app or dashboard, to Deploy and the strategy, implementation and promotion for Social Media.</li><li class="area-list-subhead">For Individuals</li><li>Learn AI</li><li>Create a digital business</li><li>Develop your own application</li><li>Automate personal tasks</li><li>Increase productivity</li><li class="area-list-subhead">For Businesses</li><li>Digital transformation</li><li>AI strategy</li><li>Operational automation</li><li>Team training</li><li>Digital product development</li><li>AI integration into existing processes</li><li class="area-list-subhead">Why Choose Pharus AI — Complete Solution</li><li>Visual identity creation</li><li>Brand Book creation</li><li>From the company\'s initial idea to the final product and its digital promotion</li><li class="area-list-subhead">Focus on Results</li><li>Productivity</li><li>Efficiency</li><li>Growth</li>',
    fr: '<li class="area-list-subhead">Prêt à créer votre prochain projet ?</li><li>Vous souhaitez développer votre identité visuelle, votre Brand Book et l\'intégrer en créant un site web, une app, un dashboard ou un agent IA cohérents avec votre identité et marque ?</li><li>Vous souhaitez apprendre à construire des solutions numériques professionnelles en utilisant les outils les plus avancés du marché ?</li><li>Planifiez une réunion stratégique avec Pharus AI et découvrez comment transformer une idée en un produit réel, accompagné par un mentorat professionnel d\'excellence.</li><li class="area-list-subhead">Conseil Stratégique</li><li>Nous aidons à définir la meilleure stratégie technologique pour chaque situation.</li><li class="area-list-subhead">Parcours Complet</li><li>De l\'Identité Visuelle de l\'entreprise, Brand Book, au Design, à la création de site web, app ou dashboard, au Deploy et à la stratégie, mise en œuvre et diffusion sur les Réseaux Sociaux.</li><li class="area-list-subhead">Pour les Particuliers</li><li>Apprendre l\'IA</li><li>Créer un business numérique</li><li>Développer sa propre application</li><li>Automatiser les tâches personnelles</li><li>Augmenter la productivité</li><li class="area-list-subhead">Pour les Entreprises</li><li>Transformation numérique</li><li>Stratégie IA</li><li>Automatisation opérationnelle</li><li>Formation des équipes</li><li>Développement de produits numériques</li><li>Intégration de l\'IA dans les processus existants</li><li class="area-list-subhead">Pourquoi Choisir Pharus AI — Solution Complète</li><li>Création d\'identité visuelle</li><li>Création de Brand Book</li><li>De l\'idée initiale de l\'entreprise au produit final et à sa diffusion numérique</li><li class="area-list-subhead">Focus sur les Résultats</li><li>Productivité</li><li>Efficacité</li><li>Croissance</li>'
  },

  'carousel.formacao-implementacao.h3': { en: 'Training and Implementation', fr: 'Formation et Mise en Œuvre' },
  'carousel.formacao-implementacao.p':  { en: 'We don\'t just teach theory. We build with you.', fr: 'Nous n\'enseignons pas seulement la théorie. Nous construisons avec vous.' },
  'carousel.formacao-implementacao.ul': {
    en: '<li>Latest Generation Technologies — We use the best tools available on the market.</li><li>Continuous Support — Support. Evolution. Continuous improvement.</li><li class="area-list-subhead">AI and Full-Stack Development Training</li><li>Learn to create complete digital solutions</li><li>From idea to final product in production</li><li>Individual training</li><li>Team training</li><li>Personalised mentoring</li>',
    fr: '<li>Technologies de Dernière Génération — Nous utilisons les meilleurs outils disponibles sur le marché.</li><li>Accompagnement Continu — Support. Évolution. Amélioration continue.</li><li class="area-list-subhead">Formation en Intelligence Artificielle et Développement Full-Stack</li><li>Apprendre à créer des solutions numériques complètes</li><li>De l\'idée au produit final en production</li><li>Formation individuelle</li><li>Formation pour équipes</li><li>Mentorat personnalisé</li>'
  },

