  'carousel.design-ia.h3': { en: 'AI-Assisted Design', fr: 'Design Assisté par IA' },
  'carousel.design-ia.p':  { en: 'Creation of visual identity, content and marketing assets with artificial intelligence.', fr: 'Création d\'identité visuelle, de contenu et d\'assets marketing avec l\'intelligence artificielle.' },
  'carousel.design-ia.ul': {
    en: '<li>The company can write its own brief</li><li>After obtaining the Business DNA, we suggest campaign ideas aligned with the business: seasonal themes, product launches, events, awareness campaigns</li><li>Landing page assets: hero image, feature screenshots, visual testimonials</li><li>Ad banners for user acquisition</li><li>Banners for Google Ads, launch posts for social networks and product photos for the website</li><li>Brand Book for internal documentation and partners</li><li>Content for launch campaign</li><li>Social Media asset generation</li><li>Generation of posts ready for Instagram, Facebook, X/Twitter, LinkedIn and YouTube (thumbnails)</li><li>Visual Identity for internal documentation and partners</li>',
    fr: '<li>L\'entreprise peut rédiger son propre brief</li><li>Après avoir obtenu le Business DNA, nous suggérons des idées de campagne alignées avec l\'activité : thèmes saisonniers, lancements de produits, événements, campagnes de sensibilisation</li><li>Assets de la landing page : hero image, captures d\'écran de fonctionnalités, témoignages visuels</li><li>Bannières publicitaires pour l\'acquisition d\'utilisateurs</li><li>Bannières pour Google Ads, posts de lancement pour les réseaux sociaux et photos de produits pour le site web</li><li>Brand Book pour la documentation interne et les partenaires</li><li>Contenu pour campagne de lancement</li><li>Génération d\'assets pour les Réseaux Sociaux</li><li>Génération de posts prêts pour Instagram, Facebook, X/Twitter, LinkedIn et YouTube (thumbnails)</li><li>Identité Visuelle pour la documentation interne et les partenaires</li>'
  },

